// Builds the chat-completions request for one support message.
// The JSON schema makes the local model answer in a fixed shape that the next node can trust.
const cfg = $('Config').first().json;

const SYSTEM_PROMPT = `You are a support analyst for a food-delivery app in Brazil.
You receive one message from a customer, a courier or a partner restaurant. Classify it.
Write "summary" and "suggested_reply" in Brazilian Portuguese.

Categories:
- late_order: the order is late or the courier is not moving
- missing_or_wrong_item: an item is missing, wrong or arrived in bad condition
- billing_refund: wrong or double charges, refunds
- app_issue: the app crashes, freezes or a feature does not work
- courier_account_payout: a courier asking about sign-up, account or payouts
- restaurant_partner: a partner restaurant asking about menu, orders or payouts
- praise: a compliment, no action needed
- other: anything else

Urgency:
- high: money charged wrongly, food safety, or an order in progress at risk
- medium: someone is waiting for a fix
- low: no one is blocked

The suggested reply is the first answer an agent would send: short, polite, specific to the message,
and it never promises a refund or a deadline that a human has not approved.`;

const schema = {
  type: 'object',
  properties: {
    category: {
      type: 'string',
      enum: ['late_order', 'missing_or_wrong_item', 'billing_refund', 'app_issue',
             'courier_account_payout', 'restaurant_partner', 'praise', 'other'],
    },
    urgency: { type: 'string', enum: ['low', 'medium', 'high'] },
    sentiment: { type: 'string', enum: ['negative', 'neutral', 'positive'] },
    summary: { type: 'string' },
    suggested_reply: { type: 'string' },
  },
  required: ['category', 'urgency', 'sentiment', 'summary', 'suggested_reply'],
  additionalProperties: false,
};

return {
  json: {
    ...$json,
    startedAt: Date.now(),
    body: {
      model: cfg.model,
      temperature: 0,
      max_tokens: cfg.maxTokens,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: `Channel: ${$json.channel}\nMessage: ${$json.text}` },
      ],
      response_format: { type: 'json_schema', json_schema: { name: 'support_triage', strict: true, schema } },
    },
  },
};

// Parses the model's answer and adds the routing rules.
// The model classifies; the team and the SLA come from a table, so they never depend on the model.
const ROUTING = {
  late_order: { team: 'Delivery operations', sla_hours: 0.5 },
  missing_or_wrong_item: { team: 'Order support', sla_hours: 4 },
  billing_refund: { team: 'Payments', sla_hours: 4 },
  app_issue: { team: 'Product and engineering', sla_hours: 24 },
  courier_account_payout: { team: 'Courier support', sla_hours: 24 },
  restaurant_partner: { team: 'Partner success', sla_hours: 24 },
  praise: { team: 'Customer experience', sla_hours: 72 },
  other: { team: 'Customer service', sla_hours: 24 },
};

const request = $('Build LLM request').item.json;
const raw = $json.choices?.[0]?.message?.content ?? '';

let triage = null;
try {
  // Reasoning models may prepend a <think> block; only the JSON after it matters.
  triage = JSON.parse(raw.replace(/<think>[\s\S]*?<\/think>/g, '').trim());
} catch (error) {
  triage = null;
}

// An answer that does not parse, or a category outside the table, goes to a person instead of being guessed.
const valid = Boolean(triage && ROUTING[triage.category]);
const route = valid ? ROUTING[triage.category] : { team: 'Human review', sla_hours: 4 };

return {
  json: {
    id: request.id,
    channel: request.channel,
    message: request.text,
    category: valid ? triage.category : 'needs_review',
    urgency: valid ? triage.urgency : 'medium',
    sentiment: valid ? triage.sentiment : '',
    summary: valid ? triage.summary : '',
    suggested_reply: valid ? triage.suggested_reply : '',
    team: route.team,
    sla_hours: route.sla_hours,
    model: $json.model ?? request.body.model,
    seconds: Math.round((Date.now() - request.startedAt) / 100) / 10,
    total_tokens: $json.usage?.total_tokens ?? null,
  },
};

// One summary for the whole run: what came in, where it went, and how long the local model took.
const rows = $input.all().map((item) => item.json);
const countBy = (key) =>
  rows.reduce((acc, row) => ({ ...acc, [row[key]]: (acc[row[key]] ?? 0) + 1 }), {});
const seconds = rows.reduce((sum, row) => sum + row.seconds, 0);

return [
  {
    json: {
      messages: rows.length,
      model: rows[0]?.model ?? null,
      by_category: countBy('category'),
      by_urgency: countBy('urgency'),
      by_team: countBy('team'),
      needs_review: rows.filter((row) => row.category === 'needs_review').length,
      high_urgency_ids: rows.filter((row) => row.urgency === 'high').map((row) => row.id),
      total_seconds: Math.round(seconds * 10) / 10,
      avg_seconds_per_message: rows.length ? Math.round((seconds / rows.length) * 10) / 10 : 0,
    },
  },
];
